// ---- spiccato2 ---------------------------------------------------------------------------------
const track3 = (() => {
  const RHYTHM = {"1":"x-------x-------","2":"x--x--x-x--x--x-","3":"xoxoxoxoxoxoxoxo"}
  // is the section playing at x, and how hard (0 = no)
  const strokeAt = x => {
    const c = chordAt(x), e = energy(x)
    if (!c || e < 1 || x >= END - 0.5) return 0
    if (!RHYTHM) return 1
    const pat = RHYTHM[e] ?? RHYTHM[2], i = floor(4 * mod(x, 4) + 1e-6), ch = pat ? pat[i] : '-'
    return (ch === 'x' ? 1 : ch === 'o' ? 0.6 : 0) * (mod(4 * x, 1) < 0.5 ? 1 : 0)
  }
  return {
  color: '#e9c46a',
  graph: x => (strokeAt(x) ? chordAt(x)[3].map(n => -1 + (n - 48) / 20) : null),
  midi: x => (strokeAt(x) ? chordAt(x)[3] : []),
  formula: ["Sp = \\Rev\\sum_j\\sum_i W^{\\text{скр}}_d\\big(f_j\\,2^{\\delta_i/1200}\\big)\\ \\text{— спиккато: смычок отскакивает; 3 + 3 + 2, в кульминации шестнадцатые с акцентом на каждую вторую}"],
  audio() {
    const S = [section('violins', { players: 4, centre: -0.4, spread: 0.5, vib: 0, attack: 0.012, release: 0.07, seed: 40 }), section('violas', { players: 3, centre: 0.2, spread: 0.4, vib: 0, attack: 0.012, release: 0.07, seed: 41 })], NONE = [], verb = hall({ size: 1.25, decay: 3.6, damp: 4600, wet: 0.34 })
    let F = S.map(() => NONE), last = null
    return x => {
      const st = strokeAt(x), on = st > 0, c = on ? chordAt(x) : null
      if (c && c !== last) { last = c; F = [c[3].map(n => hz(n + 0 - 60, C4)), c[3].map(n => hz(n + -12 - 60, C4))] }
      const lv = ([0.3,0.45,0.62,0.85][Math.max(0, energy(x))] ?? 0.4) * (0.6 + 0.4 * st)
      let l = 0, r = 0
      { const [a, b] = S[0](on ? F[0] : NONE, lv); l += 1 * a; r += 1 * b }
      { const [a, b] = S[1](on ? F[1] : NONE, lv); l += 0.8 * a; r += 0.8 * b }
      const k = 0.8 * (0.7 + 0.5 * lv)
      return verb(k * l, k * r)
    }
  },
}})()

